"""

mean_reduction_cpp_source = (
    "torch::Tensor mean_reduction_cuda(torch::Tensor x, int dim);"
)

mean_reduction_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void mean_reduction_kernel(const float* input, const int* dim_size, float* output, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        output[idx] = 0.0f;
    }
}

torch::Tensor mean_reduction_cuda(torch::Tensor x, int dim) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    mean_reduction_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), &dim, out.data_ptr<float>(), size);
    return out;
}
"""

mean_reduction = load_inline(
    name="mean_reduction",
    cpp_sources=mean_reduction_cpp_source,
